def _warn_if_insufficient(opt_count: int, limit: int, unlimit: bool, gene_set: int = None) -> None:
    """Warn when a run found no optimal sites, or fewer than the requested -l/--limit."""
    label = f" for gene set {gene_set}" if gene_set is not None else ""
    if opt_count == 0:
        print(f"WARNING: no optimal sites were found{label}.")
    elif not unlimit and opt_count < limit:
        print(f"WARNING: only {opt_count} optimal site(s) were found{label} (fewer than the requested limit of {limit}).")

def get_transcripts(fasta):
    transcripts = []
    with open(fasta, 'r') as f:
        for line in f:
            if line.startswith('>'):
                id = line.strip().split()[0][1:]
                transcripts.append(id)
    return transcripts

def check_accessions(accession_list, transcript_list):
    for accession in accession_list:
        if accession not in transcript_list:
            sys.exit(f"Error: {accession} not found in database.")

def syn_optimal_site_index(groups: dict, count: int) -> dict:
    """
    Build a {'geneset.site': guide_sequence} index of every optimal
    syn-tasiRNA site found across gene sets in a fresh pipeline run, e.g.
    {'1.1': 'ACGT...', '1.2': 'TTGC...', '2.1': 'GGCA...'}.
    """
    index = {}
    for g in range(count):
        group = groups[g]
        for o in range(1, group.get("opt", 0) + 1):
            index[f"{g + 1}.{o}"] = group["opt_r"][o]["guide"]
    return index

def syntasirna_json(group_count, groups, output_file, vector=None, cloning_oligos=None, no_offtarget=False, selected_sites=None):
    """
    Build syntasiRNA JSON output from pipeline results.

    Args:
        group_count (int): number of groups
        groups (dict): pipeline result structure
        vector (str, optional): cloning vector name
        cloning_oligos (dict, optional): {"forward": ..., "reverse": ...}
        no_offtarget (bool, optional): if True, off-target checking was
            disabled, so results are labeled generically (not optimal/
            suboptimal) and the suboptimal section is omitted
        selected_sites (list, optional): ordered 'geneset.site' labels chosen
            for cloning_oligos (e.g. ['1.1', '3.2', '2.1'])
    """

    blocks = []
    set_id = 1

    for g in range(group_count):
        group = groups[g]

        section_key = "results" if no_offtarget else "optimal"
        entry_label = "result" if no_offtarget else "optimal"

        block = {"name": f"Gene set {set_id}", section_key: {}}
        if not no_offtarget:
            block["suboptimal"] = {}

        # -------------------------
        # OPTIMAL / RESULTS
        # -------------------------
        for o in range(1, group.get("opt", 0) + 1):
            entry = group["opt_r"][o]

            hits = _extract_tf_hits(entry.get("tf", ""))

            block[section_key][f"{entry_label} {set_id}.{o}"] = {
                "syn-tasiRNA": entry.get("guide", ""),
                "TargetFinder": hits
            }

        # -------------------------
        # SUBOPTIMAL (only when off-target checking is enabled)
        # -------------------------
        if not no_offtarget:
            for s in range(1, group.get("sub", 0) + 1):
                entry = group["sub_r"][s]

                hits = _extract_tf_hits(entry.get("tf", ""))

                block["suboptimal"][f"suboptimal {set_id}.{s}"] = {
                    "syn-tasiRNA": entry.get("guide", ""),
                    "TargetFinder": hits
                }

        blocks.append(block)
        set_id += 1

    output = {"blocks": blocks}
    if vector:
        output["vector"] = vector
    if cloning_oligos:
        output["cloning_oligos"] = cloning_oligos
    if selected_sites:
        output["selected_sites"] = selected_sites

    with open(output_file, "w") as out:
        json.dump(output, out, indent=2)

    return output

def select_construct() -> str:
    """Interactively prompt the user to choose a construct type."""
    options = ["amiRNA", "syntasiRNA"]

    print("\nSelect construct type:")
    for i, name in enumerate(options, start=1):
        print(f"  {i}. {name}")

    while True:
        choice = input(f"Select construct [1-{len(options)}]: ").strip()
        if choice.isdigit() and 1 <= int(choice) <= len(options):
            return options[int(choice) - 1]
        print(f"Invalid selection '{choice}'. Please enter a number between 1 and {len(options)}.")

def convert_fasta_to_string(fasta_file):
    fasta_str = ''
    with open(fasta_file, 'r') as f:
        for line in f:
            fasta_str += line
    return fasta_str

def select_vector(construct: str) -> str:
    """Interactively prompt the user to pick a cloning vector for the given construct type."""
    vectors = list(AMIRNA_VECTORS if construct == "amiRNA" else SYNTASIRNA_VECTORS)

    print("\nAvailable cloning vectors:")
    for i, name in enumerate(vectors, start=1):
        print(f"  {i}. {name}")

    while True:
        choice = input(f"Select a vector [1-{len(vectors)}]: ").strip()
        if choice.isdigit() and 1 <= int(choice) <= len(vectors):
            return vectors[int(choice) - 1]
        print(f"Invalid selection '{choice}'. Please enter a number between 1 and {len(vectors)}.")

def vector_filename_suffix(vector: str) -> str:
    """Return a filesystem-safe suffix for a vector name (e.g. 'pMDC32B-B/c' -> 'pMDC32B-Bc')."""
    return vector.replace("/", "")

def _load_tf_cache(cache_path: Path) -> dict:
    """
    Load the shared, construct-agnostic TargetFinder result cache from a
    previous run against the same gene(s)/species in this output folder
    (see serial_jobs). TargetFinder's result for a given guide only
    depends on that guide and the background transcriptome, never on
    which construct designed it — so an amiRNA run and a syntasiRNA run
    for the same gene(s) can reuse each other's TargetFinder calls instead
    of re-invoking the (slow) external tool for guides already tested.
    """
    results = {}
    if cache_path.exists():
        try:
            with open(cache_path) as f:
                raw = json.load(f)
            # Entries without a "background" come from a cache written
            # before runs could screen against several transcriptomes.
            # There is no record of which transcriptome produced them, so
            # they are dropped rather than risk reusing a result computed
            # against a different background.
            results = {
                _tf_cache_key(entry["background"], guide_key.rsplit("\t", 1)[-1]): (entry["query_name"], entry["lines"])
                for guide_key, entry in raw.items()
                if isinstance(entry, dict) and "background" in entry
            }
        except Exception:
            results = {}
    return {"path": cache_path, "lock": threading.Lock(), "results": results}
